for i in range(int(input())):
	(n, x) = map(int, input().split())
	arr = list(map(int, input().split()))
	count = 0
	for i in range(n):
		if sorted(arr) == arr:
			break
		if arr[i] > x:
			(x, arr[i]) = (arr[i], x)
			count += 1
	print(count) if sorted(arr) == arr else print(-1)
